INSERT INTO article (category_id, title, slug, summary, content_html, content_text, author_name, source_url, source_file, content_hash, source_published_at, published_at, status, sort_order, is_featured, home_sort_order, seo_title, seo_description, seo_keywords, deleted, version)
SELECT (SELECT id FROM article_category WHERE code = 'company_news' LIMIT 1), '奥飞新材积极参与长沙市“AI赋能新质生产力”培训，助力企业科技创新升级', 'legacy-3060', '2025年5月8日至9日，由长沙市科学技术协会主办的“AI赋能新质生产力 创新驱动高质量发展”长沙市企事业（园区）、高校创新能力提升行动在环保科技产业园圆满举办。奥飞新材作为长沙市重点新材料企业，积极组织技术骨干和创新管理团队代表参加本次培训，与来自全市高校、园区及企事业单位的科技工作者共话AI赋能与高质量发展路径。 本次活动以“AI+产业融合”为主题，聚焦企事业科协能力提升与青年科技工作者创新创业需求。培训课程涵盖“企业创新方法实践”“人工智能在科技创新中的应用”“技术创新与专利保护”“数据赋能企业高质量发展服务平台”等多个前沿主题，特邀湖南大学国家超级计算长沙中心、南华生物等代表单位提供现', '<h2>奥飞新材积极参与长沙市“AI赋能新质生产力”培训，助力企业科技创新升级 - 湖南奥飞新材料有限公司</h2>
<p>2025年5月8日至9日，由长沙市科学技术协会主办的“AI赋能新质生产力 创新驱动高质量发展”长沙市企事业（园区）、高校创新能力提升行动在环保科技产业园圆满举办。奥飞新材作为长沙市重点新材料企业，积极组织技术骨干和创新管理团队代表参加本次培训，与来自全市高校、园区及企事业单位的科技工作者共话AI赋能与高质量发展路径。</p>
<figure><img src="bootstrap/legacy-news/240327f0701a173d042f3e6bf688ad250c40a0d7f65015e6b93718c07d91bd82.jpg" alt="奥飞新材积极参与长沙市“AI赋能新质生产力”培训，助力企业科技创新升级" loading="lazy"></figure>
<p>本次活动以“AI+产业融合”为主题，聚焦企事业科协能力提升与青年科技工作者创新创业需求。培训课程涵盖“企业创新方法实践”“人工智能在科技创新中的应用”“技术创新与专利保护”“数据赋能企业高质量发展服务平台”等多个前沿主题，特邀湖南大学国家超级计算长沙中心、南华生物等代表单位提供现场观摩学习机会。</p>
<p>奥飞新材参会代表表示，此次培训不仅拓宽了企业技术管理人员在AI应用及创新战略方面的视野，更加深了对数字化转型和产业升级的认识。作为一家致力于低碳环保材料和纳米气凝胶研发的高新技术企业，奥飞新材正积极将人工智能技术融入到产品研发、质量控制与客户服务等多个环节，助力企业在“双碳”战略背景下实现绿色高质量发展。</p>
<p>此次活动不仅为奥飞新材与全市科技创新资源搭建了交流平台，也为推进企业产学研融合、提升自主创新能力奠定了坚实基础。未来，奥飞新材将继续践行“创新驱动发展”战略，持续加强与高校科研机构的合作，推动人工智能、大数据等新兴技术在新材料领域的深度融合与落地应用。</p>', '2025年5月8日至9日，由长沙市科学技术协会主办的“AI赋能新质生产力 创新驱动高质量发展”长沙市企事业（园区）、高校创新能力提升行动在环保科技产业园圆满举办。奥飞新材作为长沙市重点新材料企业，积极组织技术骨干和创新管理团队代表参加本次培训，与来自全市高校、园区及企事业单位的科技工作者共话AI赋能与高质量发展路径。 本次活动以“AI+产业融合”为主题，聚焦企事业科协能力提升与青年科技工作者创新创业需求。培训课程涵盖“企业创新方法实践”“人工智能在科技创新中的应用”“技术创新与专利保护”“数据赋能企业高质量发展服务平台”等多个前沿主题，特邀湖南大学国家超级计算长沙中心、南华生物等代表单位提供现场观摩学习机会。 奥飞新材参会代表表示，此次培训不仅拓宽了企业技术管理人员在AI应用及创新战略方面的视野，更加深了对数字化转型和产业升级的认识。作为一家致力于低碳环保材料和纳米气凝胶研发的高新技术企业，奥飞新材正积极将人工智能技术融入到产品研发、质量控制与客户服务等多个环节，助力企业在“双碳”战略背景下实现绿色高质量发展。 此次活动不仅为奥飞新材与全市科技创新资源搭建了交流平台，也为推进企业产学研融合、提升自主创新能力奠定了坚实基础。未来，奥飞新材将继续践行“创新驱动发展”战略，持续加强与高校科研机构的合作，推动人工智能、大数据等新兴技术在新材料领域的深度融合与落地应用。', '共话AI赋能与高质量发展路径。', 'https://alfy.cn/3060.html', '新闻动态/公司新闻/奥飞新材积极参与长沙市“AI赋能新质生产力”培训，助力企业科技创新升级 - 湖南奥飞新材料有限公司_20260713.docx', '6c35a4d834f1b19ce28a02298cbd9ebecc5d4ff54fcebba2dcb32be51ccfebad', '2026-07-13 11:21:35', '2026-07-13 11:21:35', 'PUBLISHED', 0, 0, 0, '奥飞新材积极参与长沙市“AI赋能新质生产力”培训，助力企业科技创新升级', '2025年5月8日至9日，由长沙市科学技术协会主办的“AI赋能新质生产力 创新驱动高质量发展”长沙市企事业（园区）、高校创新能力提升行动在环保科技产业园圆满举办。奥飞新材作为长沙市重点新材料企业，积极组织技术骨干和创新管理团队代表参加本次培训，与来自全市高校、园区及企事业单位的科技工作者共话AI赋能与高质量发展路径。 本次活动以“AI+产业融合”为主题，聚焦企事业科协能力提升与青年科技工作者创新创业需求。培训课程涵盖“企业创新方法实践”“人工智能在科技创新中的应用”“技术创新与专利保护”“数据赋能企业高质量发展服务平台”等多个前沿主题，特邀湖南大学国家超级计算长沙中心、南华生物等代表单位提供现', 'company_news', 0, 0
