INSERT INTO article (category_id, title, slug, summary, content_html, content_text, author_name, source_url, source_file, content_hash, source_published_at, published_at, status, sort_order, is_featured, home_sort_order, seo_title, seo_description, seo_keywords, deleted, version)
SELECT (SELECT id FROM article_category WHERE code = 'industry_news' LIMIT 1), '2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办', 'legacy-3337', '7月19日至21日，第一届岳麓先进材料论坛暨湖南省研究生创新论坛在中南大学三一大楼603报告厅成功举办。此次论坛由粉末冶金全国重点实验室、中南大学粉末冶金研究院以及材料科学与工程学院联合主办，中南大学粉末冶金研究院研究生会和材料科学与工程学院研究生会承办。 论坛的举办得到了广泛关注。成功吸引了来自香港大学、北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等全国20余所高校及科研机构的150余名专家、学者和研究生参与，为材料科学领域的交流与合作搭建了坚实桥梁。 论坛开幕式由中南大学粉末冶金研究院院长张斗教授主持。除报告嘉宾外，中南大学粉末冶金全国重点实验室主任周科朝，国', '<h2>2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办 - 湖南奥飞新材料有限公司</h2>
<p>7月19日至21日，第一届岳麓先进材料论坛暨湖南省研究生创新论坛在中南大学三一大楼603报告厅成功举办。此次论坛由粉末冶金全国重点实验室、中南大学粉末冶金研究院以及材料科学与工程学院联合主办，中南大学粉末冶金研究院研究生会和材料科学与工程学院研究生会承办。</p>
<p>论坛的举办得到了广泛关注。成功吸引了来自香港大学、北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等全国20余所高校及科研机构的150余名专家、学者和研究生参与，为材料科学领域的交流与合作搭建了坚实桥梁。</p>
<figure><img src="bootstrap/legacy-news/01d2f7ab2f35448805f23bd66b325233013dd63613e87c02085484865b4c0336.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<p>论坛开幕式由中南大学粉末冶金研究院院长张斗教授主持。除报告嘉宾外，中南大学粉末冶金全国重点实验室主任周科朝，国防科技大学空天科学学院白书欣，中南大学粉末冶金研究院党委书记王德志，中南大学材料科学与工程学院党委书记王新平、院长李周、湖南师范大学物理与电子科学学院院长刘红荣、湖南工业大学材料与先进制造学院院长范才河、湖南科技大学材料科学与工程学院院长刘清泉等多位领导及专家出席。</p>
<figure><img src="bootstrap/legacy-news/3297621019cd796a57722fa84454ca0ec599d798d59aeb6fddea441e4ea383d3.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<p>粉末冶金全国重点实验室主任周科朝教授作为主办方代表发表致辞。他向与会人员表示了热烈的欢迎，并着重指出当前AI技术的迅猛发展既为材料科学研究带来了新的机遇，也使该领域面临着诸多挑战。他期望本次论坛能够成为一个高质量交流与合作平台，有效促进AI技术与材料科学的深度融合，从而为材料科学的创新发展注入强大动力。</p>
<figure><img src="bootstrap/legacy-news/40afb25449cd6f45d113468d70d29209972fbcfa89e2a1e372b0ee927e9e6149.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<p>北京科技大学谢建新院士以《国家新材料大数据中心建设思考》为题，深入剖析了新材料大数据中心建设的必要性和可行性。此外，香港大学陆洋教授、南方科技大学李江宇教授、国防科技大学叶益聪教授，湖南大学吴正刚教授、徐先东教授，电子科技大学蔡伟照教授，中北大学李晓峰教授，长沙理工大学金娇教授，以及中南大学杜勇教授、李瑞迪教授、李志明教授、张利军教授进行了报告分享。</p>
<figure><img src="bootstrap/legacy-news/2a82a2852b4b13a9d538747686c8da31bbf771717dd3fbc75b5687acf1a16c04.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/8c75f56dc1f65d0704363df110e8988e950020ad68ff611b28d83e6af5c5bf50.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/2950bdcf4d25b081dc6e32f20ca3e63a30013d0ea3f29ebe9d318a7a273732ae.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<p>在随后举行的湖南省研究生创新论坛中，16位来自北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等高校的杰出研究生代表以精彩的口头报告和墙报形式分享了他们的最新研究成果，展现了扎实的学术功底和创新思维。国防科技大学叶益聪教授、湖南大学徐先东教授、中南大学材料科学与工程学院蔡格梅教授和中南大学粉末冶金研究院陈超教授担任评委，为同学们的报告进行了细致入微的点评，并提出了宝贵的建议。经过激烈角逐，最终中南大学易旺等6人分获口头报告一、二、三等奖，湖南大学姜雅岚等5人获得优秀海报奖。</p>
<figure><img src="bootstrap/legacy-news/b5f6e946a4739632c3ff6fa5601b41944d9f2e3e37e69f0c548e98c36518cfc8.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<p>与此同时，另有17位同学通过精心设计的海报，生动直观地展示了各自研究中的亮点与突破，吸引了众多与会者的关注与交流。经过激烈角逐，最终易旺荣获口头报告一等奖，刘微子、李亚豪获得口头报告二等奖，高田创、余纪威、徐勋林获得口头报告三等奖，刘宇翔、张童弟、张树森、张家琪、白立顺、张飞志、武帅、舒忠良、孙鹏皓、孙楠杰获得口头报告优秀奖，姜雅岚、孙鹏皓、曹辰意、李波、程思源获得优秀海报奖。</p>
<figure><img src="bootstrap/legacy-news/be3509872165de3ed4ce52d53ea2e8d29791582a5c9243a3612dd723537d7634.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/6d41c48f0f2f76a61dab2ebb8178802403264904c2b732d0df8e13de9ae6c90f.jpg" alt="2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办" loading="lazy"></figure>', '7月19日至21日，第一届岳麓先进材料论坛暨湖南省研究生创新论坛在中南大学三一大楼603报告厅成功举办。此次论坛由粉末冶金全国重点实验室、中南大学粉末冶金研究院以及材料科学与工程学院联合主办，中南大学粉末冶金研究院研究生会和材料科学与工程学院研究生会承办。 论坛的举办得到了广泛关注。成功吸引了来自香港大学、北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等全国20余所高校及科研机构的150余名专家、学者和研究生参与，为材料科学领域的交流与合作搭建了坚实桥梁。 论坛开幕式由中南大学粉末冶金研究院院长张斗教授主持。除报告嘉宾外，中南大学粉末冶金全国重点实验室主任周科朝，国防科技大学空天科学学院白书欣，中南大学粉末冶金研究院党委书记王德志，中南大学材料科学与工程学院党委书记王新平、院长李周、湖南师范大学物理与电子科学学院院长刘红荣、湖南工业大学材料与先进制造学院院长范才河、湖南科技大学材料科学与工程学院院长刘清泉等多位领导及专家出席。 粉末冶金全国重点实验室主任周科朝教授作为主办方代表发表致辞。他向与会人员表示了热烈的欢迎，并着重指出当前AI技术的迅猛发展既为材料科学研究带来了新的机遇，也使该领域面临着诸多挑战。他期望本次论坛能够成为一个高质量交流与合作平台，有效促进AI技术与材料科学的深度融合，从而为材料科学的创新发展注入强大动力。 北京科技大学谢建新院士以《国家新材料大数据中心建设思考》为题，深入剖析了新材料大数据中心建设的必要性和可行性。此外，香港大学陆洋教授、南方科技大学李江宇教授、国防科技大学叶益聪教授，湖南大学吴正刚教授、徐先东教授，电子科技大学蔡伟照教授，中北大学李晓峰教授，长沙理工大学金娇教授，以及中南大学杜勇教授、李瑞迪教授、李志明教授、张利军教授进行了报告分享。 在随后举行的湖南省研究生创新论坛中，16位来自北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等高校的杰出研究生代表以精彩的口头报告和墙报形式分享了他们的最新研究成果，展现了扎实的学术功底和创新思维。国防科技大学叶益聪教授、湖南大学徐先东教授、中南大学材料科学与工程学院蔡格梅教授和中南大学粉末冶金研究院陈超教授担任评委，为同学们的报告进行了细致入微的点评，并提出了宝贵的建议。经过激烈角逐，最终中南大学易旺等6人分获口头报告一、二、三等奖，湖南大学姜雅岚等5人获得优秀海报奖。 与此同时，另有17位同学通过精心设计的海报，生动直观地展示了各自研究中的亮点与突破，吸引了众多与会者的关注与交流。经过激烈角逐，最终易旺荣获口头报告一等奖，刘微子、李亚豪获得口头报告二等奖，高田创、余纪威、徐勋林获得口头报告三等奖，刘宇翔、张童弟、张树森、张家琪、白立顺、张飞志、武帅、舒忠良、孙鹏皓、孙楠杰获得口头报告优秀奖，姜雅岚、孙鹏皓、曹辰意、李波、程思源获得优秀海报奖。', NULL, 'https://alfy.cn/3337.html', '新闻动态/行业新闻/2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办 - 湖南奥飞新材料有限公司_20260713.docx', 'f5fb4efd838896214e1b745a20edce1e3937b979df2b4064b71e9ad95beef5b1', '2026-07-13 10:54:57', '2026-07-13 10:54:57', 'PUBLISHED', 0, 0, 0, '2025年第一届岳麓先进材料论坛暨湖南省研究生创新论坛顺利举办', '7月19日至21日，第一届岳麓先进材料论坛暨湖南省研究生创新论坛在中南大学三一大楼603报告厅成功举办。此次论坛由粉末冶金全国重点实验室、中南大学粉末冶金研究院以及材料科学与工程学院联合主办，中南大学粉末冶金研究院研究生会和材料科学与工程学院研究生会承办。 论坛的举办得到了广泛关注。成功吸引了来自香港大学、北京科技大学、国防科技大学、华中科技大学、南方科技大学、中南大学、湖南大学等全国20余所高校及科研机构的150余名专家、学者和研究生参与，为材料科学领域的交流与合作搭建了坚实桥梁。 论坛开幕式由中南大学粉末冶金研究院院长张斗教授主持。除报告嘉宾外，中南大学粉末冶金全国重点实验室主任周科朝，国', 'industry_news', 0, 0
