INSERT INTO article (category_id, title, slug, summary, content_html, content_text, author_name, source_url, source_file, content_hash, source_published_at, published_at, status, sort_order, is_featured, home_sort_order, seo_title, seo_description, seo_keywords, deleted, version)
SELECT (SELECT id FROM article_category WHERE code = 'case' LIMIT 1), '长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏', 'legacy-d67d8efb229e80d96f11', '2026-01-29 建筑领域 2025-07-03 作者 奥飞气凝胶 近日，长沙望城区金星北路山与墅小区某栋屋顶隔热保温工程顺利落地，长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏。住户在酷暑中带来更加舒适宜人的居住体验。此次项目由奥飞新材提供全套隔热保温解决方案，严格按照专业施工工艺执行，确保质量与效率双重保障。 在施工初期，施工团队首先对屋面瓦及天沟进行全面清理，彻底铲除松动浮土与杂物，确保施工基础干净整洁。随后，分两遍均匀喷涂奥飞外墙耐候隔热涂料，整体厚度约达2mm，进一步增强屋面的耐候性与隔热性能。最后，再喷涂一遍奥飞反射隔热涂料，构建双重防护屏障，从源头反射太阳辐射', '<p>2026-01-29</p>
<p>建筑领域</p>
<p>2025-07-03 作者 奥飞气凝胶</p>
<p>近日，长沙望城区金星北路山与墅小区某栋屋顶隔热保温工程顺利落地，长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏。住户在酷暑中带来更加舒适宜人的居住体验。此次项目由奥飞新材提供全套隔热保温解决方案，严格按照专业施工工艺执行，确保质量与效率双重保障。</p>
<figure><img src="bootstrap/legacy-news/31456a8bf43b02edcbe26435571fd4dfc3b67b9ce86035a29c25285bcb60fbbd.webp" alt="长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/3d4e84f50b0866f8226b7ff8a56feb94321c3ba989ddc67b4c20f4471f69b9a5.webp" alt="长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏" loading="lazy"></figure>
<p>在施工初期，施工团队首先对屋面瓦及天沟进行全面清理，彻底铲除松动浮土与杂物，确保施工基础干净整洁。随后，分两遍均匀喷涂奥飞外墙耐候隔热涂料，整体厚度约达2mm，进一步增强屋面的耐候性与隔热性能。最后，再喷涂一遍奥飞反射隔热涂料，构建双重防护屏障，从源头反射太阳辐射，阻止热量渗透。</p>
<figure><img src="bootstrap/legacy-news/7d72a62541c4a9ac8cd105d3196f86c4d38585a1db028f637e19beaaef1ca41c.webp" alt="长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏" loading="lazy"></figure>
<p>为应对夏季高温施工挑战，项目组合理安排施工时间，选取清晨低温时段作业，分四次施工有序推进，既保障施工质量，也保障施工人员安全。</p>
<p>奥飞隔热涂料不仅具备出色的耐候性和反射性，还可显著降低建筑物内部温度，实现夏季降温、冬季保温的双重功效，有效减少空调等能耗设备的使用频率，助力绿色节能生活。</p>
<p>此次工程的顺利落地，充分展示了奥飞在建筑节能材料领域的技术实力和服务效率。未来，我们将继续以高性能的节能产品，为更多建筑项目提供专业、可靠的隔热保温解决方案。</p>
<figure><video controls preload="metadata" src="bootstrap/legacy-news/981448f2b52ae4642b5ac325fa8bb515655192c1ccee0f71cab9e33f85f227f7.mp4"></video></figure>', '2026-01-29 建筑领域 2025-07-03 作者 奥飞气凝胶 近日，长沙望城区金星北路山与墅小区某栋屋顶隔热保温工程顺利落地，长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏。住户在酷暑中带来更加舒适宜人的居住体验。此次项目由奥飞新材提供全套隔热保温解决方案，严格按照专业施工工艺执行，确保质量与效率双重保障。 在施工初期，施工团队首先对屋面瓦及天沟进行全面清理，彻底铲除松动浮土与杂物，确保施工基础干净整洁。随后，分两遍均匀喷涂奥飞外墙耐候隔热涂料，整体厚度约达2mm，进一步增强屋面的耐候性与隔热性能。最后，再喷涂一遍奥飞反射隔热涂料，构建双重防护屏障，从源头反射太阳辐射，阻止热量渗透。 为应对夏季高温施工挑战，项目组合理安排施工时间，选取清晨低温时段作业，分四次施工有序推进，既保障施工质量，也保障施工人员安全。 奥飞隔热涂料不仅具备出色的耐候性和反射性，还可显著降低建筑物内部温度，实现夏季降温、冬季保温的双重功效，有效减少空调等能耗设备的使用频率，助力绿色节能生活。 此次工程的顺利落地，充分展示了奥飞在建筑节能材料领域的技术实力和服务效率。未来，我们将继续以高性能的节能产品，为更多建筑项目提供专业、可靠的隔热保温解决方案。', '奥飞气凝胶', NULL, '相关案例/长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏.docx', '692ac34162d2af9c848732cbc79cf26ee6c3f22b91d9a570e32b9d6ea16f4515', '2026-07-10 00:00:00', '2026-07-10 00:00:00', 'PUBLISHED', 0, 0, 0, '长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏', '2026-01-29 建筑领域 2025-07-03 作者 奥飞气凝胶 近日，长沙望城区金星北路山与墅小区某栋屋顶隔热保温工程顺利落地，长沙屋顶隔热保温望城区山与墅项目圆满完工，奥飞涂料助力清凉过夏。住户在酷暑中带来更加舒适宜人的居住体验。此次项目由奥飞新材提供全套隔热保温解决方案，严格按照专业施工工艺执行，确保质量与效率双重保障。 在施工初期，施工团队首先对屋面瓦及天沟进行全面清理，彻底铲除松动浮土与杂物，确保施工基础干净整洁。随后，分两遍均匀喷涂奥飞外墙耐候隔热涂料，整体厚度约达2mm，进一步增强屋面的耐候性与隔热性能。最后，再喷涂一遍奥飞反射隔热涂料，构建双重防护屏障，从源头反射太阳辐射', 'case', 0, 0
