INSERT INTO article (category_id, title, slug, summary, content_html, content_text, author_name, source_url, source_file, content_hash, source_published_at, published_at, status, sort_order, is_featured, home_sort_order, seo_title, seo_description, seo_keywords, deleted, version)
SELECT (SELECT id FROM article_category WHERE code = 'case' LIMIT 1), '高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例', 'legacy-b7847612fbc55c178a6a', '2026-01-29 光学领域, 声学领域, 建筑领域 2025-06-18 作者 奥飞气凝胶 在“双碳”目标与绿色校园建设的大背景下，越来越多高校开始对老旧建筑进行节能改造。传统保温方式不仅施工繁琐、厚度大，还往往牺牲了空间与美观性。而奥飞新材推出的室内用气凝胶隔热涂料，则以其超薄、隔热、美观兼备的优势，在校园建筑升级中发挥了关键作用。 项目概况 项目地点：湖南长沙 中南大学 改造对象：学生宿舍楼内墙翻新 施工工艺：满批 2mm 厚度气凝胶涂料 → 打磨 → 艺术漆饰面 主要目标：提升室内隔热性能，优化墙体装饰效果，延长使用寿命 材料亮点：奥飞新材室内用气凝胶隔热涂料 （产品介绍链接：htt', '<p>2026-01-29</p>
<p>光学领域, 声学领域, 建筑领域</p>
<p>2025-06-18 作者 奥飞气凝胶</p>
<p>在“双碳”目标与绿色校园建设的大背景下，越来越多高校开始对老旧建筑进行节能改造。传统保温方式不仅施工繁琐、厚度大，还往往牺牲了空间与美观性。而奥飞新材推出的室内用气凝胶隔热涂料，则以其超薄、隔热、美观兼备的优势，在校园建筑升级中发挥了关键作用。</p>
<figure><img src="bootstrap/legacy-news/615b9a98a14807e25d9be8d2ee81af31e7765763cdd17210c7ca18a8d9c28d1a.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<p>项目概况</p>
<figure><img src="bootstrap/legacy-news/a762a34450c80d839fb27047da7c32c4a829fb2bcabcbf8ee6a9c8f6983790d4.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/9a11076483e3110b9fb9164e9ed92542c7b3c3d583197d9bc38b38c2e71f7c15.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/083279e5f0e6f2a3a0c424d868f2fb93e7dd663fe3bac16546cad606b399b105.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<p>项目地点：湖南长沙 中南大学</p>
<p>改造对象：学生宿舍楼内墙翻新</p>
<p>施工工艺：满批 2mm 厚度气凝胶涂料 → 打磨 → 艺术漆饰面</p>
<p>主要目标：提升室内隔热性能，优化墙体装饰效果，延长使用寿命</p>
<p>材料亮点：奥飞新材室内用气凝胶隔热涂料</p>
<p>（产品介绍链接：https://alfy.cn/product/interior-thermal-insulation-paint）</p>
<p>奥飞新材气凝胶涂料是专为室内保温设计的一款高性能环保材料，其核心特性包括：</p>
<p>优异隔热性能：2mm厚度即可显著阻隔室内外热交换，提升居住舒适度；</p>
<p>轻薄不占空间：相比传统保温层节省墙体厚度，适用于旧楼改造；</p>
<p>优良的饰面兼容性：施工后表面平整、易打磨，为后续艺术漆等高端饰面提供理想基底；</p>
<p>绿色环保：无甲醛、低VOC，适合教育场所长期使用；</p>
<p>施工便捷：批刮施工快速，适配大面积翻新作业。</p>
<figure><img src="bootstrap/legacy-news/e7ee90b6d5c64978e3db10bc0e449edbf9f5adef261196a17bf21af6986a6ed5.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/56830bb910f23e9dcda4d06a9c5134c4b7fd57e9dd5008756ade0fcf45dd4cfd.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<p>实施效果：隔热+美观，翻新提升一体化</p>
<p>在本项目中，施工团队先进行内墙基层处理，并采用2mm厚度满批气凝胶涂料，表面经打磨处理后，再施作艺术漆饰面。最终效果获得学校及施工单位一致好评，主要体现在：</p>
<p>隔热显著：在冬夏季节均可感受到明显的热阻隔效果，减少空调/暖气能耗；</p>
<p>饰面优美：艺术漆表面光滑自然、色彩丰富，体现现代校园审美；</p>
<p>无异味入住快：施工期间及完工后空气清新，学生可快速入住；</p>
<p>提升宿舍档次：整体焕然一新，视觉与居住体验双提升。</p>
<p>改造背后：绿色校园的示范样板</p>
<p>本次项目不仅是一次简单的宿舍翻新，更是绿色低碳理念在校园改造中的一次生动实践。奥飞新材气凝胶产品通过“隔热+美观+环保”三位一体的解决方案，助力高校构建更加节能、健康、舒适的学习与生活环境。</p>
<figure><img src="bootstrap/legacy-news/f2e810cd73a143e232bfc85662a0ccc2cec1a2ff6d77f1bf259109d5c14eb0c1.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<figure><img src="bootstrap/legacy-news/5d33ff143abd783733846472cd1fea16b1b102288680dc98e5d0a61343a52cde.webp" alt="高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例" loading="lazy"></figure>
<p>我们相信，随着高性能节能材料的持续应用，将有更多高校旧房实现功能与美感的全面升级。</p>
<p>结语：让每一面墙都能节能</p>
<p>奥飞新材将继续深耕高性能气凝胶涂料在建筑节能领域的落地实践，为学校、医院、住宅、商业场所等多元场景提供可持续的绿色解决方案。</p>
<p>如需了解更多案例细节、施工指导或产品参数，欢迎联系我们的技术团队获取一对一支持。</p>', '2026-01-29 光学领域, 声学领域, 建筑领域 2025-06-18 作者 奥飞气凝胶 在“双碳”目标与绿色校园建设的大背景下，越来越多高校开始对老旧建筑进行节能改造。传统保温方式不仅施工繁琐、厚度大，还往往牺牲了空间与美观性。而奥飞新材推出的室内用气凝胶隔热涂料，则以其超薄、隔热、美观兼备的优势，在校园建筑升级中发挥了关键作用。 项目概况 项目地点：湖南长沙 中南大学 改造对象：学生宿舍楼内墙翻新 施工工艺：满批 2mm 厚度气凝胶涂料 → 打磨 → 艺术漆饰面 主要目标：提升室内隔热性能，优化墙体装饰效果，延长使用寿命 材料亮点：奥飞新材室内用气凝胶隔热涂料 （产品介绍链接：https://alfy.cn/product/interior-thermal-insulation-paint） 奥飞新材气凝胶涂料是专为室内保温设计的一款高性能环保材料，其核心特性包括： 优异隔热性能：2mm厚度即可显著阻隔室内外热交换，提升居住舒适度； 轻薄不占空间：相比传统保温层节省墙体厚度，适用于旧楼改造； 优良的饰面兼容性：施工后表面平整、易打磨，为后续艺术漆等高端饰面提供理想基底； 绿色环保：无甲醛、低VOC，适合教育场所长期使用； 施工便捷：批刮施工快速，适配大面积翻新作业。 实施效果：隔热+美观，翻新提升一体化 在本项目中，施工团队先进行内墙基层处理，并采用2mm厚度满批气凝胶涂料，表面经打磨处理后，再施作艺术漆饰面。最终效果获得学校及施工单位一致好评，主要体现在： 隔热显著：在冬夏季节均可感受到明显的热阻隔效果，减少空调/暖气能耗； 饰面优美：艺术漆表面光滑自然、色彩丰富，体现现代校园审美； 无异味入住快：施工期间及完工后空气清新，学生可快速入住； 提升宿舍档次：整体焕然一新，视觉与居住体验双提升。 改造背后：绿色校园的示范样板 本次项目不仅是一次简单的宿舍翻新，更是绿色低碳理念在校园改造中的一次生动实践。奥飞新材气凝胶产品通过“隔热+美观+环保”三位一体的解决方案，助力高校构建更加节能、健康、舒适的学习与生活环境。 我们相信，随着高性能节能材料的持续应用，将有更多高校旧房实现功能与美感的全面升级。 结语：让每一面墙都能节能 奥飞新材将继续深耕高性能气凝胶涂料在建筑节能领域的落地实践，为学校、医院、住宅、商业场所等多元场景提供可持续的绿色解决方案。 如需了解更多案例细节、施工指导或产品参数，欢迎联系我们的技术团队获取一对一支持。', '奥飞气凝胶', NULL, '相关案例/高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例.docx', '5ae4b061540befbe99cbbbc7831371c23cb99f2a4d3d08225777b6219da17ada', '2026-07-10 00:00:00', '2026-07-10 00:00:00', 'PUBLISHED', 0, 0, 0, '高校旧楼焕新，气凝胶涂料助力节能升级——奥飞新材宿舍翻新改造案例', '2026-01-29 光学领域, 声学领域, 建筑领域 2025-06-18 作者 奥飞气凝胶 在“双碳”目标与绿色校园建设的大背景下，越来越多高校开始对老旧建筑进行节能改造。传统保温方式不仅施工繁琐、厚度大，还往往牺牲了空间与美观性。而奥飞新材推出的室内用气凝胶隔热涂料，则以其超薄、隔热、美观兼备的优势，在校园建筑升级中发挥了关键作用。 项目概况 项目地点：湖南长沙 中南大学 改造对象：学生宿舍楼内墙翻新 施工工艺：满批 2mm 厚度气凝胶涂料 → 打磨 → 艺术漆饰面 主要目标：提升室内隔热性能，优化墙体装饰效果，延长使用寿命 材料亮点：奥飞新材室内用气凝胶隔热涂料 （产品介绍链接：htt', 'case', 0, 0
